  "Subscription is the global login and {n} API key is saved. Every session can pick its account in the New Session dialog or the card's ⚙ — you'll never need /login switching again.": "サブスクリプションがグローバルログインで、{n} 件の API キーが保存されています。各セッションは新規セッションダイアログまたはカードの ⚙ でアカウントを選べます—— /login の切り替えはもう不要です。",
