  "{rows}×{cols} grid": "{rows}×{cols} グリッド",
  "{state} — {activity} (observed by VibeSpace; the agent can set its own state with vibespace-status). Click to set manually.": "{state} — {activity}（VibeSpace が観測；エージェントは vibespace-status で自分の状態を設定できます）。クリックで手動設定。",
  "~/.claude/.credentials.json — no re-login on the new instance": "~/.claude/.credentials.json——新しいインスタンスで再ログイン不要",
  "Re-login on this machine…": "このマシンで再ログイン…",
  "Log in on this machine…": "このマシンでログイン…",
  "A terminal opened — sign in as “{name}”. Only this account’s login is refreshed; every other login is untouched.": "ターミナルを開きました——「{name}」としてサインインしてください。更新されるのはこのアカウントのログインのみで、他のログインには影響しません。",
  "✓ “{name}” signed in again": "✓ 「{name}」が再ログインしました",
  "The login belongs to a DIFFERENT account ({email}) — saved as the new entry “{new}”. “{name}” stays signed out.": "このログインは別のアカウント（{email}）のものです——新しいエントリ「{new}」として保存しました。「{name}」はログアウトのままです。",
  "The login belongs to “{other}” ({email}) — its login was refreshed there instead. “{name}” stays signed out.": "このログインは「{other}」（{email}）のものです——そのエントリのログインを更新しました。「{name}」はログアウトのままです。",
  "Switched back to Local — the previously selected remote host no longer exists.": "ローカルに戻しました——以前選択していたリモートホストはもう存在しません。",
  "The machine’s global CLI login is this same subscription — its quota is shown merged here.": "このマシンのグローバル CLI ログインはこのアカウントと同じサブスクリプションです——クォータは統合表示されています。",
  "The CLI config file records {cfg} — residue of the most recent account login (relocated logins still write their identity into the global config). The active token belongs to {actual}, whose quota is shown. No action needed.": "CLI 設定ファイルに記録されている {cfg} は、直近のアカウントログインが残した痕跡です（リロケートされたログインも身分をグローバル設定に書き込みます）。実際に有効なトークンは {actual} のもので、表示中のクォータもそれです。対応は不要です。",
  "(+{n} more lines — open the file to see all)": "（あと {n} 行——全文はファイルを開いて確認）",
  "{n} urgent": "{n} 件緊急",
  "{n} high": "{n} 件高優先度",
  "{n} normal": "{n} 件通常",
  "waiting on you": "あなたの対応待ち",
  "⚠ Subscription signed out (a Console login replaced it) — pies show its last-known quota. API-billed sessions never appear here.": "⚠ サブスクリプションからサインアウトされました（Console ログインが置き換えました）——円グラフは最後に判明したクォータを表示します。API 課金のセッションはここには表示されません。",
  "✓ All set": "✓ すべて完了",
  "✓ {n} more completed…": "✓ 他 {n} 件完了…",
  "Grid snap off": "グリッドスナップ オフ",
  "Shake to bypass snap": "シェイクでスナップ解除",
  "Shake a window vigorously for ~1 second while dragging to turn off grid/edge snap for the rest of that drag (a mouse-only alternative to holding Alt)": "ドラッグ中にウィンドウを約1秒間激しく振ると、そのドラッグの残りの間だけグリッド/エッジスナップを無効化します（Alt キー長押しの代わりになるマウス操作）",
  "Shake duration (seconds)": "シェイク判定時間（秒）",
  "How long you must keep shaking before grid snap turns off. Lower = triggers faster (but easier to trigger by accident).": "グリッドスナップがオフになるまで振り続ける時間。小さいほど速く発動します（ただし誤発動しやすくなります）。",
  "Task Group folder ({name})": "タスクグループのフォルダ（{name}）",
  "In a Task Group folder — {n} session(s) here": "タスクグループのフォルダ内——ここに {n} 件のセッションがあります",
  "+ New session in a Task Group…": "＋ タスクグループで新規セッション…",
  "No group": "グループなし",
  "billing::Plan": "プラン",
  "Open working directory": "作業ディレクトリを開く",
  "⚠ Model auto-fallback: {from} → {to} (the harness switched models, e.g. capacity/overload; /model or the badge menu sets it back)": "⚠ モデルの自動フォールバック：{from} → {to}（容量/過負荷などでharnessがモデルを切り替えました。/model またはバッジメニューで戻せます）",
  "A terminal opened — sign in with the account you want to add. Your other logins are untouched; VibeSpace captures it automatically.": "ターミナルが開きました——追加したいアカウントでサインインしてください。他のログインには影響しません。VibeSpace が自動的に取り込みます。",
  "Add subscription": "サブスクリプションを追加",
  "Add subscription…": "サブスクリプションを追加…",
  "Could not start": "開始できませんでした",
  "Could not start — server unreachable": "開始できませんでした——サーバーに接続できません",
  "Subscription login could not be saved. Check the login terminal for details, then try again.": "サブスクリプションのログインを保存できませんでした。ログイン用ターミナルの詳細を確認して、もう一度お試しください。",
  "Name this subscription (e.g. Work Max, Personal Max)": "このサブスクに名前を付ける（例：仕事Max、個人Max）",
  "Open a terminal session on this subscription": "このサブスクでターミナルセッションを開く",
  "Remove this subscription from VibeSpace (deletes its stored login)": "この サブスクを VibeSpace から削除（保存されたログインを削除）",
