  "Account email": "アカウントのメール",
  "Email of this Anthropic account. Used to recognize when it is the same account as a machine login (their usage then shows merged).": "この Anthropic アカウントのメールアドレス。マシンのログインと同一アカウントかの判定に使われます(同一なら使用量が統合表示されます)。",
  "Account was removed from VibeSpace — history kept": "このアカウントは VibeSpace から削除済み — 履歴は保持",
  "Same account as the machine CLI login — includes its (unattributed) usage too": "このマシンの CLI ログインと同一アカウント — その(未帰属の)使用量も含みます",
  "Sessions that ran on the machine’s own login (no VibeSpace account selected)": "マシン自身のログインで実行されたセッション(VibeSpace アカウント未選択)",
  "Claude CLI login": "Claude マシンログイン",
  "Claude CLI login (unattributed)": "Claude マシンログイン(未帰属)",
  "Codex CLI login": "Codex マシンログイン",
  "Codex CLI login (unattributed)": "Codex マシンログイン(未帰属)",
  "Declare which ChatGPT account this is — the email links it to the machine login for merged usage": "どの ChatGPT アカウントかを指定 — メールでマシンのログインと同一アカウントか判定します(使用量は統合表示)",
  "Default account · refreshes as its sessions run": "デフォルトアカウント · セッション実行時に自動更新",
  "Email of this ChatGPT account. Used to recognize when it is the same account as a machine login (their usage then shows merged).": "この ChatGPT アカウントのメールアドレス。マシンのログインと同一アカウントかの判定に使われます(同一なら使用量が統合表示されます)。",
  "No usage captured yet for this account — run a session on it.": "このアカウントの使用量はまだ記録されていません — このアカウントでセッションを実行してください。",
  "Refreshes as this account’s sessions run": "このアカウントのセッション実行時に自動更新",
