  "Prompt cache hit rate (last turn): {pct}% of input tokens were read from cache ({read} of {total}). Higher = cheaper + faster.": "プロンプトキャッシュのヒット率（直前のターン）：入力トークンの {pct}% がキャッシュから読み込まれました（{total} 中 {read}）。高いほど安く高速です。",
