  "Live view — updates every few seconds. Phase names, labels and token totals appear when the run finishes. Open any agent to watch its transcript.": "ライブビュー——数秒ごとに更新。フェーズ名・ラベル・トークン合計は実行終了後に表示されます。任意のエージェントを開いてトランスクリプトを閲覧できます。",
