  "Re-authorize \"{name}\"": "\"{name}\" を再認可",
  "Re-authorize {provider}…": "{provider} を再認可…",
  "Remote path": "リモートパス",
  "Remote path (optional)": "リモートパス(任意)",
  "Saving token & reconnecting…": "トークンを保存して再接続中…",
  "Sign in with {provider}": "{provider} でサインイン",
  "User": "ユーザー名",
  "Hide empty thinking blocks": "空の思考ブロックを隠す",
  "Thinking cards with no visible text (redacted or zero-length thinking) are hidden. They never count toward or break run collapsing. Turn off to see every thinking card — applies to open chats instantly.": "可視テキストのない思考カード(マスク済みまたは長さゼロの思考)を隠します。連続折りたたみの数に入らず、途切れさせることもありません。オフにするとすべての思考カードを表示 — 開いているチャットに即時反映。",
  "Credential only — this token can’t open the storage root; add submounts (specific buckets/paths) under it.": "資格情報のみ — このトークンではストレージのルートを開けません。その下にサブマウント(特定のバケット/パス)を追加してください。",
  "Add a submount (a specific bucket/path of this storage)": "サブマウントを追加(このストレージの特定のバケット/パス)",
  "This storage type doesn’t support submounts": "このストレージタイプはサブマウントに対応していません",
  "New submount under \"{name}\"": "\"{name}\" の下に新しいサブマウント",
  "What happens when closing a session window: detach and keep it running (default — the session stays in the sidebar for re-attach), or terminate it. Automation helper terminals always terminate.": "セッションウィンドウを閉じたときの動作：切り離して実行を継続（デフォルト — セッションはサイドバーに残り再アタッチできます）、または終了。自動化ヘルパーターミナルは常に終了します。",
  "= “{name}”": "= “{name}”",
  "A server over SSH (SFTP)": "SSH サーバー (SFTP)",
  "Access key": "アクセスキー",
  "Advanced: an absolute path if you need it in a specific place.": "上級：特定の場所に置きたい場合は絶対パスを指定。",
  "Advanced: you can also paste the JSON from `rclone authorize \"drive\"` run elsewhere.": "上級：別の場所で実行した `rclone authorize \"drive\"` の JSON を貼り付けることもできます。",
  "Advanced: your own Google Cloud OAuth client — avoids rclone's shared quota. Used by Connect too.": "上級：自分の Google Cloud OAuth クライアント——rclone の共有クォータを回避。「接続」ボタンでも使用されます。",
  "Another VibeSpace": "別の VibeSpace",
  "Any backend rclone supports — see rclone.org/docs. Params below map to that backend's config keys.": "rclone が対応する任意のバックエンド——rclone.org/docs 参照。下のパラメータはその設定キーに対応。",
  "Ask the other VibeSpace to create one under Storage → “Share a local folder”.": "相手の VibeSpace の ストレージ → 「ローカルフォルダを共有」で作成してもらってください。",
  "Bridge link — embeds a scoped token; treat it like a key": "ブリッジリンク——限定トークンを含みます。鍵として扱ってください",
  "Bucket (storage container)": "バケット（ストレージコンテナ）",
  "Cloud storage (S3 / MinIO)": "クラウドストレージ (S3 / MinIO)",
  "Connect Google Drive": "Google Drive を接続",
  "Copy link": "リンクをコピー",
  "Create link": "リンクを作成",
  "Custom / advanced (rclone)": "カスタム / 上級 (rclone)",
  "Custom OAuth client ID (optional)": "カスタム OAuth クライアント ID（任意）",
  "Custom OAuth client secret (optional)": "カスタム OAuth クライアントシークレット（任意）",
  "Direct CephFS link — embeds a scoped key; only works inside this cluster. Send over company chat only; Revoke under Bridge tokens.": "CephFS 直結リンク——限定キーを含み、このクラスタ内でのみ有効。社内チャットのみで送付。「ブリッジトークン」から失効可能。",
  "Display name (optional)": "表示名（任意）",
  "Endpoint": "エンドポイント",
  "Extra options (key = value per line)": "追加オプション（1 行に key = value）",
  "Failed to start authorization": "認可の開始に失敗しました",
  "Find storage in this config": "この設定からストレージを検出",
  "Folder (optional, blank = whole Drive)": "フォルダ（任意、空 = ドライブ全体）",
  "Folder to share (absolute path on this machine)": "共有するフォルダ（このマシンの絶対パス）",
  "Folder under this storage (empty = share everything)": "このストレージ内のフォルダ（空 = 全体を共有）",
  "Folder under {path} (empty = share everything)": "{path} 内のフォルダ（空 = 全体を共有）",
  "From registered host (optional)": "登録済みホストから選択（任意）",
  "From your provider’s “Access Keys” / API credentials page.": "ストレージ事業者の「Access Keys」/ API 認証情報ページから。",
  "Generic WebDAV": "汎用 WebDAV",
  "Google Drive access": "Google Drive 認可",
  "Import & connect": "インポートして接続",
