  "Imported {n} remotes": "{n} 個のリモートをインポートしました",
  "Importing…": "インポート中…",
  "Label": "ラベル",
  "Limit this connection to one folder inside the bucket. Leave blank for the whole bucket.": "この接続をバケット内の 1 フォルダに限定。空欄でバケット全体。",
  "Link copied": "リンクをコピーしました",
  "Link expires after (days, max 7)": "リンク有効期限（日、最大 7）",
  "Mount as": "マウントモード",
  "Mount token (vsmt_…)": "マウントトークン (vsmt_…)",
  "Nextcloud: Settings → Files shows this address. Use an app password if you have 2FA.": "Nextcloud：設定 → ファイル にこのアドレスが表示されます。2FA 利用時はアプリパスワードを。",
  "No remotes found in that config.": "この設定にリモートが見つかりません。",
  "Parameters (one key = value per line)": "パラメータ（1 行に key = value）",
  "Parse failed": "解析に失敗しました",
  "Passed to the underlying transfer engine (rclone) — custom API keys, tuning, provider quirks. See rclone.org/docs.": "下層の転送エンジン (rclone) に渡されます——カスタム API キー、チューニング等。rclone.org/docs 参照。",
  "Password (if no key)": "パスワード（鍵がない場合）",
  "Password / app token": "パスワード / アプリトークン",
  "Paste the contents of your rclone.conf (from `rclone config file` — usually ~/.config/rclone/rclone.conf). Every remote inside it becomes a mount you can pick.": "rclone.conf の内容を貼り付けてください（`rclone config file` で場所確認——通常 ~/.config/rclone/rclone.conf）。中の各リモートが選択可能なマウントになります。",
  "Paste the share link": "共有リンクを貼り付けてください",
  "Path within the remote (optional)": "リモート内パス（任意）",
  "Pick at least one remote.": "少なくとも 1 つ選択してください。",
  "Private key path (absolute) — or use password": "秘密鍵パス（絶対パス）——またはパスワードを使用",
  "Read-only": "読み取り専用",
  "Read-write": "読み書き",
  "Remove \"{name}\"?": "「{name}」を削除しますか？",
  "SSH host": "SSH ホスト",
