  "ChatGPT": "ChatGPT",
  "ChatGPT (Codex)": "ChatGPT (Codex)",
  "Checking the connection…": "接続を確認中…",
  "Claude": "Claude",
  "Click ⟳ to re-scan this host.": "⟳ をクリックしてこのホストを再スキャン。",
  "Codex": "Codex",
  "Complete this account’s login in Manage agents first.": "先に Manage agents でこのアカウントのログインを完了してください。",
  "Connecting to {host}…": "{host} に接続中…",
  "Connection lost before the goal was set — your command was restored to the input": "目標を設定する前に接続が失われました——入力内容は入力欄に復元されました",
  "Could not change the default account — {reason}": "既定のアカウントを変更できませんでした — {reason}",
