  'Compacting context… (a large conversation takes 1–2 minutes — Stop cancels it)': 'コンテキストを圧縮中…（大きな会話は 1〜2 分かかります。Stop で取り消されます）',
  'Click again to cancel the running compaction': 'もう一度クリックすると実行中の圧縮を取り消します',
