  "The package is validated before it is placed under data/plugins/<id>/. Plugins that ask for capabilities beyond the sandbox are enabled only after you review them.": "パッケージは検証後に data/plugins/<id>/ に配置されます。サンドボックスを超える権限を求めるプラグインは、内容を確認した後にのみ有効化されます。",
