  "Plugin window not available: {id}": "プラグインウィンドウを利用できません: {id}",
  "Plugin: {name}": "プラグイン: {name}",
  "Trusted client code: runs in this page with the same access as VibeSpace itself — it can read everything this page can, including your session, and act as you. Equivalent to adding code to VibeSpace.": "信頼済みクライアントコード: このページ内で VibeSpace 自体と同じアクセス権で動作します — セッションを含めこのページが読めるものすべてを読み、あなたとして操作できます。VibeSpace にコードを追加するのと同等です。",
  "Sandboxed UI: its windows run in an isolated origin and cannot read this page.": "サンドボックス UI: ウィンドウは分離オリジンで動作し、このページを読めません。",
  "Runs its own server process, confined to its plugin folder and its data folder.": "独自のサーバープロセスを実行します（プラグインフォルダとデータフォルダに限定）。",
  "Server: read files under {paths}": "サーバー: {paths} 配下のファイルを読み取り",
  "Server: write AND read files under {paths}": "サーバー: {paths} 配下のファイルを書き込みおよび読み取り",
  "Server: run other programs (child processes) — those programs are NOT confined and can reach anything the server user can.": "サーバー: 他のプログラム（子プロセス）を実行 — それらは制限されず、サーバーユーザーが到達できるものすべてに到達できます。",
  "Server: network access to {hosts} — declared only; the sandbox does not restrict network access.": "サーバー: {hosts} へのネットワークアクセス — 宣言のみ。サンドボックスはネットワークを制限しません。",
  "Adds agent tools every session can call: {names} — installed as programs on every session's PATH (this machine, ssh hosts and paired devices) and run OUTSIDE the plugin sandbox.": "すべてのセッションが呼べるエージェントツールを追加: {names} — 各セッションの PATH（このマシン・ssh ホスト・ペアリング済みデバイス）にプログラムとして配置され、プラグインのサンドボックス外で実行されます。",
  "This is a different package under the same id — it was left disabled. Review what it asks for and enable it again.": "同じ id の別パッケージです — 無効のままにしました。要求する権限を確認してから再度有効にしてください。",
